    36	    @Transactional
    37	    public Map<String, Object> register(Dtos.RegisterReq req) {
    38	        String email = req.email().trim().toLowerCase();
    39	        if (email.length() > 200) throw Api.error(400, "VALIDATION_EMAIL_LENGTH", "Email is too long");
    40	        checkPassword(req.password());
    41	        String displayName = req.displayName() == null ? null : req.displayName().trim();
    42	        if (displayName != null && displayName.length() > 100) {
    43	            throw Api.error(400, "VALIDATION_INVALID", "displayName must be at most 100 characters");
    44	        }
    45	        try {
    46	            jdbc.update("INSERT INTO users(email,password_hash,display_name,role) VALUES (?,?,?,'EMPLOYEE')",
    47	                    email, encoder.encode(req.password()), displayName);
    48	        } catch (DuplicateKeyException e) {
    49	            throw Api.error(409, "AUTH_EMAIL_EXISTS", "Email already registered");
    50	        }
    51	        Long id = jdbc.queryForObject("SELECT id FROM users WHERE email=?", Long.class, email);
    52	        Map<String, Object> user = new LinkedHashMap<>();
    53	        user.put("id", id);
    54	        user.put("email", email);
    55	        user.put("role", "EMPLOYEE");
