    59	    public Map<String, Object> login(Dtos.LoginReq req, String ip) {
    60	        String email = req.email().trim().toLowerCase();
    61	        limiter.check("login:ip:" + ip, 20, 60_000);
    62	        limiter.check("login:ipmail:" + ip + ":" + email, 10, 60_000);
    63	        Map<String, Object> row;
    64	        try {
    65	            row = jdbc.queryForMap("SELECT id,email,password_hash,role,status FROM users WHERE email=?", email);
    66	        } catch (Exception e) {
    67	            throw Api.error(401, "AUTH_INVALID_CREDENTIALS", "Invalid email or password");
    68	        }
    69	        if (!"ACTIVE".equals(row.get("status")) || !encoder.matches(req.password(), String.valueOf(row.get("password_hash")))) {
    70	            throw Api.error(401, "AUTH_INVALID_CREDENTIALS", "Invalid email or password");
    71	        }
    72	        long id = ((Number) row.get("id")).longValue();
    73	        String role = String.valueOf(row.get("role"));
    74	        String access = jwt.issue(new UserPrincipal(id, email, role));
    75	        String refresh = issueRefresh(id);
    76	        Map<String, Object> user = new LinkedHashMap<>();
    77	        user.put("id", id);
    78	        user.put("email", email);
    79	        user.put("role", role);
    80	        Map<String, Object> data = new LinkedHashMap<>();
    81	        data.put("accessToken", access);
    82	        data.put("refreshToken", refresh);
    83	        data.put("expiresIn", jwt.accessTtlSeconds());
    84	        data.put("user", user);
    85	        return data;
    86	    }
