   135	    private String issueRefresh(long userId) {
   136	        byte[] raw = new byte[32];
   137	        random.nextBytes(raw);
   138	        String token = Base64.getUrlEncoder().withoutPadding().encodeToString(raw);
   139	        jdbc.update("INSERT INTO refresh_tokens(user_id,token_hash,expires_at) VALUES (?,?,?)",
   140	                userId, Util.sha256(token), LocalDateTime.now().plusDays(7));
