    20	@Service
    21	public class JwtService {
    22	    private static final Logger log = LoggerFactory.getLogger(JwtService.class);
    23	    private static final Base64.Encoder B64 = Base64.getUrlEncoder().withoutPadding();
    24	    private static final Base64.Decoder B64D = Base64.getUrlDecoder();
    25	
    26	    private final byte[] secret;
    27	    private final ObjectMapper mapper;
    28	    private final long accessTtl;
    29	
    30	    public JwtService(@Value("${webox.jwt.secret:}") String configuredSecret,
    31	                      @Value("${webox.jwt.access-ttl-seconds:7200}") long accessTtl,
    32	                      ObjectMapper mapper) {
    33	        this.mapper = mapper;
    34	        this.accessTtl = accessTtl;
    35	        if (configuredSecret == null || configuredSecret.isBlank()) {
    36	            byte[] r = new byte[32];
    37	            new SecureRandom().nextBytes(r);
    38	            this.secret = r;
    39	            log.warn("JWT_SECRET not set; using an ephemeral random key (tokens invalid after restart)");
    40	        } else {
    41	            this.secret = configuredSecret.getBytes(StandardCharsets.UTF_8);
    42	        }
    43	    }
    44	
    45	    public long accessTtlSeconds() { return accessTtl; }
    46	
    47	    public String issue(UserPrincipal p) {
    48	        long now = System.currentTimeMillis() / 1000;
    49	        Map<String, Object> payload = new LinkedHashMap<>();
    50	        payload.put("sub", String.valueOf(p.id()));
    51	        payload.put("email", p.email());
    52	        payload.put("role", p.role());
    53	        payload.put("iat", now);
    54	        payload.put("exp", now + accessTtl);
    55	        try {
    56	            String header = B64.encodeToString("{\"alg\":\"HS256\",\"typ\":\"JWT\"}".getBytes(StandardCharsets.UTF_8));
    57	            String body = B64.encodeToString(mapper.writeValueAsBytes(payload));
    58	            String sig = B64.encodeToString(hmac(header + "." + body));
    59	            return header + "." + body + "." + sig;
    60	        } catch (Exception e) {
    61	            throw new IllegalStateException("JWT signing failed", e);
    62	        }
    63	    }
    64	
    65	    public UserPrincipal parse(String token) {
    66	        try {
    67	            String[] parts = token.split("\\.");
    68	            if (parts.length != 3) throw Api.error(401, "AUTH_TOKEN_INVALID", "Invalid token");
    69	            byte[] expected = hmac(parts[0] + "." + parts[1]);
    70	            byte[] actual = B64D.decode(parts[2]);
    71	            if (!MessageDigest.isEqual(expected, actual)) {
    72	                throw Api.error(401, "AUTH_TOKEN_INVALID", "Invalid token");
    73	            }
    74	            Map<?, ?> payload = mapper.readValue(B64D.decode(parts[1]), Map.class);
    75	            long exp = ((Number) payload.get("exp")).longValue();
    76	            if (System.currentTimeMillis() / 1000 >= exp) {
    77	                throw Api.error(401, "AUTH_TOKEN_INVALID", "Token expired");
    78	            }
    79	            return new UserPrincipal(Long.parseLong(String.valueOf(payload.get("sub"))),
    80	                    String.valueOf(payload.get("email")), String.valueOf(payload.get("role")));
    81	        } catch (ApiException e) {
    82	            throw e;
    83	        } catch (Exception e) {
    84	            throw Api.error(401, "AUTH_TOKEN_INVALID", "Invalid token");
    85	        }
    86	    }
    87	
    88	    private byte[] hmac(String data) throws Exception {
    89	        Mac mac = Mac.getInstance("HmacSHA256");
    90	        mac.init(new SecretKeySpec(secret, "HmacSHA256"));
    91	        return mac.doFinal(data.getBytes(StandardCharsets.UTF_8));
    92	    }
