    97	        if (Util.intVal(row.get("revoked")) != 0
    98	                || ((java.sql.Timestamp) row.get("expires_at")).toLocalDateTime().isBefore(LocalDateTime.now())) {
    99	            throw Api.error(401, "AUTH_TOKEN_INVALID", "Invalid refresh token");
   100	        }
   101	        long tokenId = ((Number) row.get("id")).longValue();
   102	        long userId = ((Number) row.get("user_id")).longValue();
   103	        int revoked = jdbc.update("UPDATE refresh_tokens SET revoked=1 WHERE id=? AND revoked=0", tokenId);
   104	        if (revoked == 0) throw Api.error(401, "AUTH_TOKEN_INVALID", "Invalid refresh token");
   105	        Map<String, Object> user = jdbc.queryForMap("SELECT id,email,role FROM users WHERE id=?", userId);
   106	        String access = jwt.issue(new UserPrincipal(userId, String.valueOf(user.get("email")), String.valueOf(user.get("role"))));
   107	        String refresh = issueRefresh(userId);
   108	        Map<String, Object> u = new LinkedHashMap<>();
   109	        u.put("id", userId);
   110	        u.put("email", user.get("email"));
   111	        u.put("role", user.get("role"));
   112	        Map<String, Object> data = new LinkedHashMap<>();
   113	        data.put("accessToken", access);
   114	        data.put("refreshToken", refresh);
   115	        data.put("expiresIn", jwt.accessTtlSeconds());
   116	        data.put("user", u);
