    26	    @Override
    27	    protected void doFilterInternal(HttpServletRequest req, HttpServletResponse res, FilterChain chain)
    28	            throws ServletException, IOException {
    29	        String header = req.getHeader("Authorization");
    30	        if (header != null && header.startsWith("Bearer ")) {
    31	            try {
    32	                UserPrincipal p = jwtService.parse(header.substring(7).trim());
    33	                UsernamePasswordAuthenticationToken auth = new UsernamePasswordAuthenticationToken(
    34	                        p, null, List.of(new SimpleGrantedAuthority("ROLE_" + p.role())));
    35	                SecurityContextHolder.getContext().setAuthentication(auth);
    36	                MDC.put("userId", String.valueOf(p.id()));
    37	            } catch (ApiException e) {
    38	                res.setStatus(401);
    39	                res.setContentType("application/json;charset=UTF-8");
    40	                res.getWriter().write("{\"code\":\"" + e.getCode() + "\",\"message\":\"" + e.getMessage()
    41	                        + "\",\"data\":null,\"requestId\":\"" + MDC.get("requestId") + "\"}");
    42	                return;
    43	            }
    44	        }
    45	        try {
    46	            chain.doFilter(req, res);
    47	        } finally {
    48	            MDC.remove("userId");
    49	        }
    50	    }
