92	    91	    public Outcome submit(UserPrincipal user, Dtos.SubmitReq req, String key) {
93	    92	        if (key == null || key.isBlank()) {
94	    93	            throw Api.error(400, "IDEMPOTENCY_KEY_REQUIRED", "Idempotency-Key header is required");
95	    94	        }
96	    95	        if (key.length() < 8 || key.length() > 64) {
97	    96	            throw Api.error(400, "IDEMPOTENCY_KEY_REQUIRED", "Idempotency-Key must be 8-64 characters");
98	    97	        }
99	    98	        String hash = Util.canonicalSubmit(req);
100	    99	        IdempotencyService.Claim claim = idem.claim(user.id(), key, hash);
101	   100	        if (claim.replay()) {
102	   101	            Map<String, Object> stored = Util.parseMap(claim.replayBody());
103	   102	            return new Outcome(claim.replayStatus(), stored);
104	   103	        }
105	   104	        RedisStockService.Preallocation prealloc = null;
106	   105	        try {
107	   106	            LocalDate ctxDate;
108	   107	            try {
109	   108	                ctxDate = Util.resolveMeal(
110	   109	                        req.deliveryDate() == null || req.deliveryDate().isBlank() ? null : LocalDate.parse(req.deliveryDate()),
111	   110	                        req.mealType(), RequestContext.now()).date();
112	   111	            } catch (ApiException e) {
113	   112	                idem.complete(claim.id(), e.getStatus(), errorBody(e), null);
114	   113	                throw e;
115	   114	            } catch (Exception e) {
116	   115	                ctxDate = RequestContext.today();
117	   116	            }
118	   117	            prealloc = new RedisStockService.Preallocation(ctxDate);
119	   118	            Map<String, Object> data;
120	   119	            try {
121	   120	                data = tx.execute(user.id(), user.email(), req, prealloc, key);
122	   121	            } catch (ConcurrencyFailureException deadlock) {
123	   122	                redisStock.compensate(prealloc);
124	   123	                prealloc = new RedisStockService.Preallocation(ctxDate);
125	   124	                data = tx.execute(user.id(), user.email(), req, prealloc, key);
126	   125	            } catch (DuplicateKeyException dup) {
127	   126	                redisStock.compensate(prealloc);
128	   127	                ApiException mapped = mapDuplicate(dup, user.id(), req);
129	   128	                idem.complete(claim.id(), mapped.getStatus(), errorBody(mapped), null);
130	   129	                throw mapped;
131	   130	            }
132	   131	            idem.complete(claim.id(), 201, Map.of("code", "OK", "message", "Order placed", "data", data),
133	   132	                    ((Number) data.get("orderId")).longValue());
134	   133	            return new Outcome(201, Map.of("code", "OK", "message", "Order placed", "data", data));
135	   134	        } catch (ApiException e) {
136	   135	            if (prealloc != null) redisStock.compensate(prealloc);
137	   136	            idem.complete(claim.id(), e.getStatus(), errorBody(e), null);
138	   137	            throw e;
139	   138	        } catch (RuntimeException e) {
140	   139	            if (prealloc != null) redisStock.compensate(prealloc);
141	   140	            idem.fail(claim.id());
142	   141	            throw e;
143	   142	        }
144	   143	    }
