267	   266	    public Map<String, Object> cancel(UserPrincipal user, long orderId, String reason) {
268	   267	        List<Map<String, Object>> rows = jdbc.queryForList("SELECT * FROM orders WHERE id=?", orderId);
269	   268	        if (rows.isEmpty()) throw Api.error(404, "ORDER_NOT_FOUND", "Order not found");
270	   269	        Map<String, Object> o = rows.get(0);
271	   270	        long owner = ((Number) o.get("user_id")).longValue();
272	   271	        if (!user.isAdmin() && owner != user.id()) throw Api.error(404, "ORDER_NOT_FOUND", "Order not found");
273	   272	        if (reason != null && reason.length() > 200) {
274	   273	            throw Api.error(400, "VALIDATION_REASON_REQUIRED", "Reason must be at most 200 characters");
275	   274	        }
276	   275	        if (user.isAdmin() && (reason == null || reason.isBlank())) {
277	   276	            throw Api.error(400, "VALIDATION_REASON_REQUIRED", "A reason is required for admin operations");
278	   277	        }
279	   278	        String status = String.valueOf(o.get("status"));
280	   279	        int n = jdbc.update("UPDATE orders SET status='Cancelled', cancelled_at=NOW(3), cancel_reason=? "
281	   280	                + "WHERE id=? AND status='Pending'", reason, orderId);
282	   281	        if (n == 0) {
283	   282	            if ("Cancelled".equals(status) || "Confirmed".equals(status) || "Completed".equals(status)) {
284	   283	                throw Api.error(409, "ORDER_STATE_INVALID", "Only pending orders can be cancelled");
285	   284	            }
286	   285	            throw Api.error(409, "ORDER_STATE_INVALID", "Order state changed, please retry");
287	   286	        }
288	   287	        LocalDate date = ((java.sql.Date) o.get("delivery_date")).toLocalDate();
289	   288	        for (Map<String, Object> r : aggregatedItems(orderId)) {
290	   289	            long dishId = ((Number) r.get("dish_id")).longValue();
291	   290	            int qty = Util.intVal(r.get("qty"));
292	   291	            inventory.release(orderId, dishId, date, qty, user.email(), reason == null ? "CANCELLED" : reason);
293	   292	            redisStock.sync(date, dishId, inventory.available(dishId, date));
294	   293	        }
295	   294	        if (user.isAdmin()) {
296	   295	            audit.log("ORDER_CANCEL", "ORDER", String.valueOf(orderId),
297	   296	                    Map.of("status", status), Map.of("status", "Cancelled"), reason);
298	   297	        }
299	   298	        Map<String, Object> data = new LinkedHashMap<>();
300	   299	        data.put("orderId", orderId);
301	   300	        data.put("status", "Cancelled");
302	   301	        data.put("cancelledAt", Util.iso(jdbc.queryForObject("SELECT cancelled_at FROM orders WHERE id=?", Timestamp.class, orderId)));
303	   302	        return data;
304	   303	    }
