329	   328	    public void adminPatchStatus(long orderId, String toStatus, String reason) {
330	   329	        if (reason == null || reason.isBlank() || reason.length() > 200) {
331	   330	            throw Api.error(400, "VALIDATION_REASON_REQUIRED", "A reason of 1-200 characters is required");
332	   331	        }
333	   332	        if (!List.of("Confirmed", "Completed", "Cancelled").contains(toStatus)) {
334	   333	            throw Api.error(400, "VALIDATION_INVALID", "Invalid target status");
335	   334	        }
336	   335	        List<Map<String, Object>> rows = jdbc.queryForList("SELECT * FROM orders WHERE id=?", orderId);
337	   336	        if (rows.isEmpty()) throw Api.error(404, "ORDER_NOT_FOUND", "Order not found");
338	   337	        Map<String, Object> o = rows.get(0);
339	   338	        String from = String.valueOf(o.get("status"));
340	   339	        if (!OrderStateMachine.canTransition(from, toStatus)) {
341	   340	            throw Api.error(409, "ORDER_STATE_INVALID", "Illegal order state transition " + from + " -> " + toStatus);
342	   341	        }
343	   342	        int n = jdbc.update("UPDATE orders SET status=?, cancelled_at=CASE WHEN ?='Cancelled' THEN NOW(3) ELSE cancelled_at END, "
344	   343	                        + "cancel_reason=CASE WHEN ?='Cancelled' THEN ? ELSE cancel_reason END WHERE id=? AND status=?",
345	   344	                toStatus, toStatus, toStatus, reason, orderId, from);
346	   345	        if (n == 0) throw Api.error(409, "ORDER_STATE_INVALID", "Order state changed, please retry");
347	   346	        LocalDate date = ((java.sql.Date) o.get("delivery_date")).toLocalDate();
348	   347	        if ("Confirmed".equals(toStatus)) {
349	   348	            for (Map<String, Object> r : aggregatedItems(orderId)) {
350	   349	                long dishId = ((Number) r.get("dish_id")).longValue();
351	   350	                inventory.confirm(orderId, dishId, date, Util.intVal(r.get("qty")), "admin", reason);
352	   351	            }
353	   352	        } else if ("Cancelled".equals(toStatus)) {
354	   353	            for (Map<String, Object> r : aggregatedItems(orderId)) {
355	   354	                long dishId = ((Number) r.get("dish_id")).longValue();
356	   355	                inventory.release(orderId, dishId, date, Util.intVal(r.get("qty")), "admin", reason);
357	   356	                redisStock.sync(date, dishId, inventory.available(dishId, date));
358	   357	            }
359	   358	        }
360	   359	        audit.log("ORDER_STATUS", "ORDER", String.valueOf(orderId),
361	   360	                Map.of("status", from), Map.of("status", toStatus), reason);
362	   361	    }
