630	    38	        }
631	    39	        for (int attempt = 0; attempt < 11; attempt++) {
632	    40	            Map<String, Object> row = jdbc.queryForMap(
633	    41	                    "SELECT id,request_hash,status,response_status,response_body,updated_at FROM idempotency_records "
634	    42	                            + "WHERE user_id=? AND idem_key=?", userId, key);
