640	    48	            String status = String.valueOf(row.get("status"));
641	    49	            if ("COMPLETED".equals(status)) {
642	    50	                return new Claim(id, ((Number) row.get("response_status")).intValue(),
643	    51	                        row.get("response_body") == null ? null : String.valueOf(row.get("response_body")));
644	    52	            }
645	    53	            if ("FAILED".equals(status)) {
646	    54	                int n = jdbc.update("UPDATE idempotency_records SET status='IN_PROGRESS' WHERE id=? AND status='FAILED'", id);
647	    55	                if (n == 1) return new Claim(id, null, null);
648	    56	                continue;
649	    57	            }
