    23	    public record Claim(long id, Integer replayStatus, String replayBody) {
    24	        public boolean replay() { return replayStatus != null; }
    25	    }
    26	
    27	    /** T0: claims the key in an independent autocommit transaction. */
    28	    public Claim claim(long userId, String key, String hash) {
    29	        try {
    30	            jdbc.update("INSERT INTO idempotency_records(user_id,idem_key,request_hash,status,expires_at) "
    31	                            + "VALUES (?,?,?,'IN_PROGRESS',?)",
    32	                    userId, key, hash, LocalDateTime.now().plusHours(24));
    33	            Long id = jdbc.queryForObject(
    34	                    "SELECT id FROM idempotency_records WHERE user_id=? AND idem_key=?", Long.class, userId, key);
    35	            return new Claim(id, null, null);
    36	        } catch (DuplicateKeyException ignored) {
    37	            // fall through to the replay / conflict path
    38	        }
    39	        for (int attempt = 0; attempt < 11; attempt++) {
    40	            Map<String, Object> row = jdbc.queryForMap(
    41	                    "SELECT id,request_hash,status,response_status,response_body,updated_at FROM idempotency_records "
    42	                            + "WHERE user_id=? AND idem_key=?", userId, key);
    43	            String existingHash = String.valueOf(row.get("request_hash"));
    44	            if (!existingHash.equals(hash)) {
    45	                throw Api.error(409, "IDEMPOTENCY_CONFLICT", "Idempotency-Key was used with a different request body");
    46	            }
    47	            long id = ((Number) row.get("id")).longValue();
    48	            String status = String.valueOf(row.get("status"));
    49	            if ("COMPLETED".equals(status)) {
    50	                return new Claim(id, ((Number) row.get("response_status")).intValue(),
    51	                        row.get("response_body") == null ? null : String.valueOf(row.get("response_body")));
    52	            }
    53	            if ("FAILED".equals(status)) {
    54	                int n = jdbc.update("UPDATE idempotency_records SET status='IN_PROGRESS' WHERE id=? AND status='FAILED'", id);
    55	                if (n == 1) return new Claim(id, null, null);
    56	                continue;
    57	            }
    58	            Object updatedRaw = row.get("updated_at");
    59	            LocalDateTime updated = updatedRaw instanceof LocalDateTime ldt ? ldt
    60	                    : updatedRaw instanceof Timestamp ts ? ts.toLocalDateTime() : null;
    61	            if (updated != null && updated.isBefore(LocalDateTime.now().minusSeconds(30))) {
    62	                int n = jdbc.update("UPDATE idempotency_records SET status='IN_PROGRESS' "
    63	                        + "WHERE id=? AND status='IN_PROGRESS' AND updated_at=?", id, updated);
    64	                if (n == 1) return new Claim(id, null, null);
    65	                continue;
    66	            }
    67	            try {
    68	                Thread.sleep(200);
    69	            } catch (InterruptedException e) {
    70	                Thread.currentThread().interrupt();
    71	                break;
    72	            }
    73	        }
    74	        throw Api.error(409, "IDEMPOTENCY_CONFLICT", "A request with this Idempotency-Key is still in progress");
    75	    }
