    78	    @Transactional(propagation = Propagation.REQUIRES_NEW)
    79	    public void complete(long id, int status, Map<String, Object> body, Long orderId) {
    80	        jdbc.update("UPDATE idempotency_records SET status='COMPLETED', response_status=?, response_body=?, order_id=? WHERE id=?",
    81	                status, Util.json(body), orderId, id);
    82	    }
    83	
    84	    @Transactional(propagation = Propagation.REQUIRES_NEW)
    85	    public void fail(long id) {
    86	        jdbc.update("UPDATE idempotency_records SET status='FAILED', response_status=500 WHERE id=? AND status='IN_PROGRESS'", id);
    87	    }
