   102	        if (!redis.enabled()) return;
   103	        try { redis.set(key(date, dishId), String.valueOf(Math.max(0, available)), ttl(date)); }
   104	        catch (Exception e) { log.debug("Redis sync skipped: {}", e.getMessage()); }
   105	    }
