    35	    public boolean enabled() { return enabled; }
    36	
    37	    public boolean ping() {
    38	        if (!enabled) return false;
    39	        try {
    40	            Object r = command("PING");
    41	            return "PONG".equals(String.valueOf(r));
    42	        } catch (Exception e) {
    43	            return false;
    44	        }
    45	    }
