    76	    public Object command(String... args) {
    77	        if (!enabled) throw new IllegalStateException("redis disabled");
    78	        try (Socket socket = new Socket()) {
    79	            socket.connect(new InetSocketAddress(host, port), timeoutMs);
    80	            socket.setSoTimeout(timeoutMs);
    81	            OutputStream out = new BufferedOutputStream(socket.getOutputStream());
    82	            StringBuilder sb = new StringBuilder("*").append(args.length).append("\r\n");
    83	            for (String a : args) {
    84	                byte[] b = a.getBytes(StandardCharsets.UTF_8);
    85	                sb.append("$").append(b.length).append("\r\n").append(a).append("\r\n");
    86	            }
    87	            out.write(sb.toString().getBytes(StandardCharsets.UTF_8));
    88	            out.flush();
    89	            InputStream in = new BufferedInputStream(socket.getInputStream());
    90	            return read(in);
    91	        } catch (Exception e) {
    92	            throw new IllegalStateException("redis command failed: " + e.getMessage(), e);
    93	        }
    94	    }
    95	
    96	    private Object read(InputStream in) throws Exception {
    97	        int type = in.read();
    98	        if (type < 0) throw new IllegalStateException("empty redis response");
    99	        String line = readLine(in);
   100	        switch (type) {
   101	            case '+': return line;
   102	            case '-': throw new IllegalStateException("redis error: " + line);
   103	            case ':': return Long.parseLong(line);
   104	            case '$': {
   105	                int len = Integer.parseInt(line);
   106	                if (len < 0) return null;
   107	                byte[] buf = in.readNBytes(len);
   108	                readLine(in);
   109	                return new String(buf, StandardCharsets.UTF_8);
   110	            }
   111	            case '*': {
   112	                int n = Integer.parseInt(line);
   113	                if (n < 0) return null;
   114	                Object[] arr = new Object[n];
   115	                for (int i = 0; i < n; i++) arr[i] = read(in);
   116	                return arr;
   117	            }
   118	            default: throw new IllegalStateException("unknown redis reply type " + type);
   119	        }
   120	    }
   121	
   122	    private String readLine(InputStream in) throws Exception {
   123	        StringBuilder sb = new StringBuilder();
   124	        int c;
   125	        while ((c = in.read()) != -1) {
   126	            if (c == '\r') {
   127	                int n = in.read();
   128	                if (n == '\n') break;
   129	                sb.append((char) c).append((char) n);
   130	            } else {
   131	                sb.append((char) c);
   132	            }
   133	        }
   134	        return sb.toString();
   135	    }
