   115	    public static Effective resolveMeal(LocalDate requestedDate, String requestedMeal, ZonedDateTime now) {
   116	        LocalDate today = now.toLocalDate();
   117	        LocalTime time = now.toLocalTime();
   118	        LocalDate date = requestedDate;
   119	        String meal = requestedMeal;
   120	        boolean auto = false;
   121	        if (date == null && meal == null) {
   122	            if (time.isBefore(LocalTime.of(10, 0))) { date = today; meal = "Lunch"; }
   123	            else if (time.isBefore(LocalTime.of(15, 0))) { date = today; meal = "Dinner"; }
   124	            else { date = today.plusDays(1); meal = "Lunch"; }
   125	            return new Effective(date, meal, false);
   126	        }
   127	        if (date == null) date = today;
   128	        if (date.isBefore(today)) {
   129	            throw Api.error(400, "VALIDATION_DATE_PAST", "Delivery date cannot be in the past");
   130	        }
   131	        if (meal == null) meal = time.isBefore(LocalTime.of(10, 0)) ? "Lunch" : time.isBefore(LocalTime.of(15, 0)) ? "Dinner" : "Lunch";
   132	        if (!MEALS.contains(meal)) throw Api.error(400, "VALIDATION_INVALID", "Invalid mealType");
   133	        LocalTime cutoff = "Lunch".equals(meal) ? LocalTime.of(10, 0) : LocalTime.of(15, 0);
   134	        if (!now.toLocalDateTime().isBefore(ldt(date, cutoff))) {
   135	            auto = true;
   136	            if (time.isBefore(LocalTime.of(15, 0)) && date.equals(today)) { meal = "Dinner"; }
   137	            else { date = today.plusDays(1); meal = "Lunch"; }
   138	            if (date.isBefore(today)) throw Api.error(409, "ORDER_MEAL_UNAVAILABLE", "No meal can be ordered");
   139	        }
   140	        return new Effective(date, meal, auto);
   141	    }
