    33	    /** Atomic conditional reservation. Returns {before, after}. */
    34	    public int[] reserve(long dishId, LocalDate date, int qty) {
    35	        int n = jdbc.update("UPDATE dish_daily_stock SET reserved_qty=reserved_qty+?, version=version+1 "
    36	                        + "WHERE dish_id=? AND serve_date=? AND total_qty-reserved_qty-sold_qty>=?",
    37	                qty, dishId, date, qty);
    38	        if (n == 0) {
    39	            int avail = available(dishId, date);
    40	            Map<String, Object> detail = new LinkedHashMap<>();
    41	            detail.put("dishId", dishId);
    42	            detail.put("requested", qty);
    43	            detail.put("available", avail);
    44	            Map<String, Object> data = new LinkedHashMap<>();
    45	            data.put("details", List.of(detail));
    46	            throw Api.error(409, "STOCK_INSUFFICIENT", "Some dishes are sold out or insufficient", data);
    47	        }
    48	        int after = available(dishId, date);
    49	        publish(dishId, after);
    50	        return new int[]{after + qty, after};
