    59	    /** Release reserved stock exactly once, guarded by ledger business key. */
    60	    public void release(long orderId, long dishId, LocalDate date, int qty, String operator, String reason) {
    61	        String businessKey = "ORD:" + orderId + ":D:" + dishId + ":RELEASE";
    62	        Map<String, Object> row = lockStock(dishId, date, qty);
    63	        int before = ((Number) row.get("available")).intValue();
    64	        int inserted = jdbc.update("INSERT IGNORE INTO inventory_ledger"
    65	                        + "(order_id,dish_id,serve_date,entry_type,qty,before_available,after_available,business_key,operator,reason) "
    66	                        + "VALUES (?,?,?,'RELEASE',?,?,?,?,?,?)",
    67	                orderId, dishId, date, qty, before, before + qty, businessKey, operator, reason);
    68	        if (inserted == 0) return; // already released
    69	        int n = jdbc.update("UPDATE dish_daily_stock SET reserved_qty=reserved_qty-?, version=version+1 "
    70	                + "WHERE dish_id=? AND serve_date=? AND reserved_qty>=?", qty, dishId, date, qty);
    71	        if (n == 0) throw Api.error(409, "ORDER_STATE_INVALID", "Reserved stock is inconsistent");
    72	        publish(dishId, before + qty);
    73	    }
