    75	    /** Move reserved -> sold exactly once. */
    76	    public void confirm(long orderId, long dishId, LocalDate date, int qty, String operator, String reason) {
    77	        String businessKey = "ORD:" + orderId + ":D:" + dishId + ":CONFIRM";
    78	        Map<String, Object> row = lockStock(dishId, date, qty);
    79	        int before = ((Number) row.get("available")).intValue();
    80	        int inserted = jdbc.update("INSERT IGNORE INTO inventory_ledger"
    81	                        + "(order_id,dish_id,serve_date,entry_type,qty,before_available,after_available,business_key,operator,reason) "
    82	                        + "VALUES (?,?,?,'CONFIRM',?,?,?,?,?,?)",
    83	                orderId, dishId, date, qty, before, before, businessKey, operator, reason);
    84	        if (inserted == 0) return;
    85	        int n = jdbc.update("UPDATE dish_daily_stock SET reserved_qty=reserved_qty-?, sold_qty=sold_qty+?, version=version+1 "
    86	                + "WHERE dish_id=? AND serve_date=? AND reserved_qty>=?", qty, qty, dishId, date, qty);
    87	        if (n == 0) throw Api.error(409, "ORDER_STATE_INVALID", "Reserved stock is inconsistent");
    88	    }
