    90	    public void reserveLedger(long orderId, long dishId, LocalDate date, int qty, int before, int after, String operator) {
    91	        jdbc.update("INSERT IGNORE INTO inventory_ledger"
    92	                        + "(order_id,dish_id,serve_date,entry_type,qty,before_available,after_available,business_key,operator,reason) "
    93	                        + "VALUES (?,?,?,'RESERVE',?,?,?,?,?,?)",
    94	                orderId, dishId, date, qty, before, after, "ORD:" + orderId + ":D:" + dishId + ":RESERVE", operator, null);
