    97	    public void adjust(long dishId, LocalDate date, int delta, String operator, String reason) {
    98	        int n = jdbc.update("UPDATE dish_daily_stock SET total_qty=total_qty+?, version=version+1 "
    99	                + "WHERE dish_id=? AND serve_date=? AND total_qty+?>=reserved_qty+sold_qty", delta, dishId, date, delta);
   100	        if (n == 0) throw Api.error(409, "STOCK_INSUFFICIENT", "Adjusted total cannot be lower than reserved + sold");
   101	        int after = available(dishId, date);
   102	        int before = after - delta;
