    43	    private String key(LocalDate date, long dishId) { return "webox:stock:" + date + ":" + dishId; }
    44	
    45	    private int ttl(LocalDate date) {
    46	        long secs = Duration.between(LocalDateTime.now(), date.atTime(LocalTime.of(23, 59, 59))).getSeconds();
    47	        return (int) Math.max(60, secs);
    48	    }
