    14	/**
    15	 * Minimal RESP (Redis protocol) client. Kept dependency-free so that Redis remains optional
    16	 * and any connectivity failure can be handled as a graceful degradation by callers.
    17	 */
    18	@Component
    19	public class RedisClient {
    20	    private final boolean enabled;
    21	    private final String host;
    22	    private final int port;
    23	    private final int timeoutMs;
    24	
    25	    public RedisClient(@Value("${webox.redis.enabled:true}") boolean enabled,
    26	                       @Value("${webox.redis.host:127.0.0.1}") String host,
    27	                       @Value("${webox.redis.port:6379}") int port,
    28	                       @Value("${webox.redis.timeout-ms:300}") int timeoutMs) {
    29	        this.enabled = enabled;
    30	        this.host = host;
    31	        this.port = port;
    32	        this.timeoutMs = timeoutMs;
    33	    }
    34	
    35	    public boolean enabled() { return enabled; }
    36	
    37	    public boolean ping() {
    38	        if (!enabled) return false;
    39	        try {
    40	            Object r = command("PING");
    41	            return "PONG".equals(String.valueOf(r));
    42	        } catch (Exception e) {
    43	            return false;
    44	        }
    45	    }
    46	
    47	    public String get(String key) {
    48	        Object r = command("GET", key);
    49	        return r == null ? null : String.valueOf(r);
    50	    }
    51	
    52	    public void set(String key, String value, int ttlSeconds) {
    53	        command("SET", key, value, "EX", String.valueOf(ttlSeconds));
    54	    }
    55	
    56	    public long decrBy(String key, long n) {
    57	        Object r = command("DECRBY", key, String.valueOf(n));
    58	        return ((Number) r).longValue();
    59	    }
    60	
    61	    public long incrBy(String key, long n) {
    62	        Object r = command("INCRBY", key, String.valueOf(n));
    63	        return ((Number) r).longValue();
    64	    }
    65	
    66	    /** Lua preallocation: returns 1 ok, 0 insufficient, -1 key missing. */
    67	    public long prealloc(String key, long qty) {
    68	        String lua = "local v=tonumber(redis.call('GET',KEYS[1]) or '-1') "
    69	                + "if v<0 then return -1 end "
    70	                + "if v<tonumber(ARGV[1]) then return 0 end "
    71	                + "redis.call('DECRBY',KEYS[1],ARGV[1]) return 1";
    72	        Object r = command("EVAL", lua, "1", key, String.valueOf(qty));
    73	        return ((Number) r).longValue();
    74	    }
