412	    15	    public void check(String key, int limit, long windowMs) {
413	    16	        long now = System.currentTimeMillis();
414	    17	        Deque<Long> q = hits.computeIfAbsent(key, k -> new ArrayDeque<>());
415	    18	        synchronized (q) {
416	    19	            while (!q.isEmpty() && now - q.peekFirst() > windowMs) q.pollFirst();
417	    20	            if (q.size() >= limit) throw Api.error(429, "RATE_LIMITED", "Too many requests");
418	    21	            q.addLast(now);
419	    22	        }
420	    23	    }
