553	    44	    private List<String> split(String sql) {
554	    45	        StringBuilder cleaned = new StringBuilder();
555	    46	        for (String line : sql.split("\n")) {
556	    47	            String t = line.stripLeading();
557	    48	            if (t.startsWith("--") || t.startsWith("SET ") || t.isBlank()) continue;
558	    49	            cleaned.append(line).append('\n');
559	    50	        }
560	    51	        List<String> out = new ArrayList<>();
561	    52	        StringBuilder cur = new StringBuilder();
562	    53	        boolean inSingle = false;
563	    54	        char[] chars = cleaned.toString().toCharArray();
564	    55	        for (int i = 0; i < chars.length; i++) {
565	    56	            char c = chars[i];
566	    57	            if (c == '\'' ) {
567	    58	                boolean escaped = i > 0 && chars[i - 1] == '\\';
568	    59	                if (!escaped) inSingle = !inSingle;
569	    60	            }
570	    61	            if (c == ';' && !inSingle) {
571	    62	                out.add(cur.toString().trim());
572	    63	                cur.setLength(0);
573	    64	            } else {
574	    65	                cur.append(c);
575	    66	            }
576	    67	        }
577	    68	        if (!cur.toString().isBlank()) out.add(cur.toString().trim());
578	    69	        return out;
579	    70	    }
