    19	@Component
    20	@Order(Ordered.HIGHEST_PRECEDENCE)
    21	public class RequestIdFilter extends OncePerRequestFilter {
    22	    @Value("${spring.profiles.active:default}")
    23	    private String activeProfile;
    24	
    25	    @Value("${webox.test.clock-enabled:false}")
    26	    private boolean clockEnabled;
    27	
    28	    @Override
    29	    protected void doFilterInternal(HttpServletRequest req, HttpServletResponse res, FilterChain chain)
    30	            throws ServletException, IOException {
    31	        String rid = UUID.randomUUID().toString();
    32	        MDC.put("requestId", rid);
    33	        res.setHeader("X-Request-Id", rid);
    34	        res.setHeader("Access-Control-Expose-Headers", "X-Request-Id");
    35	        try {
    36	            String clock = req.getHeader("X-Test-Clock");
    37	            if (clock != null && !clock.isBlank()) {
    38	                boolean testProfile = activeProfile != null && activeProfile.contains("test");
    39	                if (!testProfile || !clockEnabled) {
    40	                    writeError(res, 400, "VALIDATION_TEST_CLOCK_FORBIDDEN",
    41	                            "X-Test-Clock is only allowed in test profile");
    42	                    return;
    43	                }
    44	                try {
    45	                    RequestContext.setTestClock(OffsetDateTime.parse(clock).toInstant());
    46	                } catch (DateTimeParseException e) {
    47	                    writeError(res, 400, "VALIDATION_TEST_CLOCK_FORBIDDEN", "Invalid X-Test-Clock value");
    48	                    return;
    49	                }
    50	            }
    51	            chain.doFilter(req, res);
    52	        } finally {
    53	            RequestContext.clearTestClock();
    54	            MDC.remove("requestId");
    55	        }
    56	    }
    57	
    58	    private void writeError(HttpServletResponse res, int status, String code, String msg) throws IOException {
    59	        res.setStatus(status);
    60	        res.setContentType("application/json;charset=UTF-8");
    61	        res.getWriter().write("{\"code\":\"" + code + "\",\"message\":\"" + msg +
    62	                "\",\"data\":null,\"requestId\":\"" + RequestContext.requestId() + "\"}");
    63	    }
