    10	/** In-memory sliding-window limiter (single instance demo). */
    11	@Component
    12	public class RateLimiter {
    13	    private final Map<String, Deque<Long>> hits = new ConcurrentHashMap<>();
    14	
    15	    public void check(String key, int limit, long windowMs) {
    16	        long now = System.currentTimeMillis();
    17	        Deque<Long> q = hits.computeIfAbsent(key, k -> new ArrayDeque<>());
    18	        synchronized (q) {
    19	            while (!q.isEmpty() && now - q.peekFirst() > windowMs) q.pollFirst();
    20	            if (q.size() >= limit) throw Api.error(429, "RATE_LIMITED", "Too many requests");
    21	            q.addLast(now);
    22	        }
    23	    }
