     8	import org.springframework.jdbc.core.JdbcTemplate;
     9	import org.springframework.stereotype.Component;
    10	
    11	import java.nio.charset.StandardCharsets;
    12	import java.util.ArrayList;
    13	import java.util.List;
    14	
    15	/** Creates the 17-table schema and seed data on first start (idempotent). */
    16	@Component
    17	public class DbBootstrap implements ApplicationRunner {
    18	    private static final Logger log = LoggerFactory.getLogger(DbBootstrap.class);
    19	    private final JdbcTemplate jdbc;
    20	
    21	    public DbBootstrap(JdbcTemplate jdbc) {
    22	        this.jdbc = jdbc;
    23	    }
    24	
    25	    @Override
    26	    public void run(ApplicationArguments args) throws Exception {
    27	        Integer tables = jdbc.queryForObject(
    28	                "SELECT COUNT(*) FROM information_schema.tables WHERE table_schema=DATABASE() AND table_name='users'",
    29	                Integer.class);
    30	        if (tables != null && tables > 0) {
    31	            log.info("Database schema present; skipping bootstrap");
    32	            return;
    33	        }
    34	        String sql = new String(new ClassPathResource("db/schema.sql").getInputStream().readAllBytes(),
    35	                StandardCharsets.UTF_8);
    36	        List<String> statements = split(sql);
    37	        log.info("Bootstrapping database with {} statements", statements.size());
    38	        for (String s : statements) {
    39	            if (!s.isBlank()) jdbc.execute(s);
    40	        }
    41	        log.info("Database bootstrap complete");
    42	    }
    43	
    44	    private List<String> split(String sql) {
    45	        StringBuilder cleaned = new StringBuilder();
    46	        for (String line : sql.split("\n")) {
    47	            String t = line.stripLeading();
    48	            if (t.startsWith("--") || t.startsWith("SET ") || t.isBlank()) continue;
    49	            cleaned.append(line).append('\n');
    50	        }
    51	        List<String> out = new ArrayList<>();
    52	        StringBuilder cur = new StringBuilder();
    53	        boolean inSingle = false;
    54	        char[] chars = cleaned.toString().toCharArray();
    55	        for (int i = 0; i < chars.length; i++) {
    56	            char c = chars[i];
    57	            if (c == '\'' ) {
    58	                boolean escaped = i > 0 && chars[i - 1] == '\\';
    59	                if (!escaped) inSingle = !inSingle;
    60	            }
    61	            if (c == ';' && !inSingle) {
    62	                out.add(cur.toString().trim());
    63	                cur.setLength(0);
    64	            } else {
    65	                cur.append(c);
    66	            }
    67	        }
    68	        if (!cur.toString().isBlank()) out.add(cur.toString().trim());
    69	        return out;
    70	    }
