    26	
    27	    /** Releases Pending orders older than 30 minutes exactly once (CAS + ledger unique key). */
    28	    @Scheduled(fixedDelay = 60000, initialDelay = 15000)
    29	    public void releaseTimedOutOrders() {
    30	        List<Map<String, Object>> rows = jdbc.queryForList(
    31	                "SELECT id FROM orders WHERE status='Pending' AND created_at < NOW(3) - INTERVAL 30 MINUTE LIMIT 100");
    32	        int released = 0;
    33	        for (Map<String, Object> r : rows) {
    34	            try {
    35	                if (orders.timeoutCancel(((Number) r.get("id")).longValue())) released++;
    36	            } catch (Exception e) {
    37	                log.warn("Timeout release failed for order {}: {}", r.get("id"), e.getMessage());
    38	            }
    39	        }
    40	        if (released > 0) log.info("Timeout released {} pending orders", released);
    41	    }
