141	   140	        if (file == null || file.isEmpty()) throw Api.error(400, "VALIDATION_IMAGE", "Image file is required");
142	   141	        if (file.getSize() > 5 * 1024 * 1024) throw Api.error(400, "VALIDATION_IMAGE", "Image must be at most 5MB");
