307	   306	    public Map<String, Object> reconcile(String dateStr) {
308	   307	        LocalDate date = dateStr == null || dateStr.isBlank() ? RequestContext.today()
309	   308	                : Util.parseDate(dateStr, "VALIDATION_INVALID");
310	   309	        List<Map<String, Object>> drift = new ArrayList<>();
311	   310	        List<Map<String, Object>> rows = jdbc.queryForList(
312	   311	                "SELECT s.dish_id, s.total_qty, s.total_qty-s.reserved_qty-s.sold_qty AS book_available, "
313	   312	                        + "s.total_qty - COALESCE(SUM(CASE l.entry_type WHEN 'RESERVE' THEN l.qty WHEN 'RELEASE' THEN -l.qty ELSE 0 END),0) AS ledger_derived "
314	   313	                        + "FROM dish_daily_stock s LEFT JOIN inventory_ledger l "
315	   314	                        + "ON l.dish_id=s.dish_id AND l.serve_date=s.serve_date "
316	   315	                        + "WHERE s.serve_date=? GROUP BY s.dish_id,s.total_qty,s.reserved_qty,s.sold_qty", date);
317	   316	        for (Map<String, Object> r : rows) {
318	   317	            long book = Util.cents(r.get("book_available"));
319	   318	            long derived = Util.cents(r.get("ledger_derived"));
320	   319	            if (book != derived) {
321	   320	                Map<String, Object> d = new LinkedHashMap<>();
322	   321	                d.put("dishId", r.get("dish_id"));
323	   322	                d.put("bookAvailable", book);
324	   323	                d.put("ledgerDerived", derived);
325	   324	                drift.add(d);
326	   325	            }
327	   326	        }
328	   327	        Map<String, Object> data = new LinkedHashMap<>();
329	   328	        data.put("date", date.toString());
330	   329	        data.put("checked", rows.size());
331	   330	        data.put("drift", drift);
332	   331	        return data;
333	   332	    }
