   170	    private void validateDish(Dtos.DishReq req) {
   171	        if (req.name() == null || req.name().isBlank() || req.name().length() > 100) {
   172	            throw Api.error(400, "VALIDATION_INVALID", "name is required (max 100)");
   173	        }
   174	        if (req.description() == null || req.description().length() > 1000) {
