   180	        if (req.category() == null || !Util.CATEGORIES.contains(req.category())) {
   181	            throw Api.error(400, "VALIDATION_CATEGORY", "Invalid category");
   182	        }
   183	        if (req.protein() == null || req.protein().length() > 50) {
   184	            throw Api.error(400, "VALIDATION_INVALID", "protein is required (max 50)");
