   399	    public Map<String, Object> dashboard(String dateStr) {
   400	        LocalDate date = dateStr == null || dateStr.isBlank() ? RequestContext.today()
   401	                : Util.parseDate(dateStr, "VALIDATION_INVALID");
   402	        Map<String, Object> today = new LinkedHashMap<>();
   403	        int orders = count("SELECT COUNT(*) FROM orders WHERE delivery_date=? AND status<>'Cancelled'", date);
   404	        long revenue = jdbc.queryForObject("SELECT COALESCE(SUM(total_cents),0) FROM orders WHERE delivery_date=? AND status<>'Cancelled'",
   405	                Long.class, date);
   406	        today.put("orders", orders);
   407	        today.put("revenueCents", revenue);
   408	        today.put("completed", count("SELECT COUNT(*) FROM orders WHERE delivery_date=? AND status='Completed'", date));
   409	        today.put("pending", count("SELECT COUNT(*) FROM orders WHERE delivery_date=? AND status='Pending'", date));
   410	        today.put("cancelled", count("SELECT COUNT(*) FROM orders WHERE delivery_date=? AND status='Cancelled'", date));
   411	
   412	        List<Map<String, Object>> topDishes = new ArrayList<>();
   413	        for (Map<String, Object> r : jdbc.queryForList(
   414	                "SELECT oi.dish_id, oi.dish_name AS name, SUM(oi.qty) AS sold FROM order_items oi "
   415	                        + "JOIN orders o ON o.id=oi.order_id WHERE o.delivery_date=? AND o.status<>'Cancelled' "
   416	                        + "GROUP BY oi.dish_id,oi.dish_name ORDER BY sold DESC LIMIT 5", date)) {
   417	            Map<String, Object> m = new LinkedHashMap<>();
   418	            m.put("dishId", r.get("dish_id"));
   419	            m.put("name", r.get("name"));
   420	            m.put("soldQty", Util.intVal(r.get("sold")));
   421	            topDishes.add(m);
   422	        }
   423	        Map<String, Object> mealSplit = new LinkedHashMap<>();
   424	        mealSplit.put("lunch", count("SELECT COUNT(*) FROM orders WHERE delivery_date=? AND status<>'Cancelled' AND meal_type='Lunch'", date));
   425	        mealSplit.put("dinner", count("SELECT COUNT(*) FROM orders WHERE delivery_date=? AND status<>'Cancelled' AND meal_type='Dinner'", date));
   426	
   427	        List<Map<String, Object>> trend = new ArrayList<>();
   428	        for (int i = 6; i >= 0; i--) {
   429	            LocalDate d = date.minusDays(i);
   430	            Map<String, Object> t = new LinkedHashMap<>();
   431	            t.put("date", d.toString());
   432	            t.put("orders", count("SELECT COUNT(*) FROM orders WHERE delivery_date=? AND status<>'Cancelled'", d));
   433	            t.put("revenueCents", jdbc.queryForObject(
   434	                    "SELECT COALESCE(SUM(total_cents),0) FROM orders WHERE delivery_date=? AND status<>'Cancelled'", Long.class, d));
   435	            trend.add(t);
   436	        }
   437	
   438	        List<Map<String, Object>> lowStock = new ArrayList<>();
   439	        for (Map<String, Object> r : jdbc.queryForList(
   440	                "SELECT s.dish_id, d.name, s.total_qty-s.reserved_qty-s.sold_qty AS available FROM dish_daily_stock s "
   441	                        + "JOIN dishes d ON d.id=s.dish_id WHERE s.serve_date=? "
   442	                        + "HAVING available>=0 AND available<=3 ORDER BY available", date)) {
   443	            Map<String, Object> m = new LinkedHashMap<>();
   444	            m.put("dishId", r.get("dish_id"));
   445	            m.put("name", r.get("name"));
   446	            m.put("available", Math.max(0, Util.intVal(r.get("available"))));
   447	            lowStock.add(m);
   448	        }
   449	
   450	        Map<String, Object> data = new LinkedHashMap<>();
   451	        data.put("today", today);
   452	        data.put("topDishes", topDishes);
   453	        data.put("mealSplit", mealSplit);
   454	        data.put("trend", trend);
   455	        data.put("lowStock", lowStock);
   456	        return data;
   457	    }
