159	   158	            List<String> dishAllergens = Util.parseList((String) r.get("allergens"));
160	   159	            if (dishAllergens.stream().anyMatch(allergens::contains)) continue;
161	   160	            String category = String.valueOf(r.get("category"));
162	   161	            long price = Util.cents(r.get("price_cents"));
163	   162	            double score = 0;
164	   163	            if (preferred.contains(category)) score += num(w.get("preferredCategory"), 3);
165	   164	            if (spice != null && spice.equals(String.valueOf(r.get("spice_level")))) score += num(w.get("spiceMatch"), 2);
166	   165	            if (budgetMax == null || price <= budgetMax) score += num(w.get("budgetFit"), 2);
167	   166	            if (r.get("protein") != null) score += num(w.get("protein"), 1);
168	   167	            out.add(new Candidate(id, String.valueOf(r.get("name")), category,
169	   168	                    String.valueOf(r.get("spice_level")), price, avail,
170	   169	                    String.valueOf(r.get("protein")), score));
171	   170	        }
172	   171	        out.sort(Comparator.comparingDouble(Candidate::score).reversed().thenComparing(Candidate::name));
