372	    33	    public long redeem(String ticket, String ip) {
373	    34	        Ticket t = tickets.get(ticket);
374	    35	        if (t == null) return -1;
375	    36	        synchronized (t) {
376	    37	            if (t.expiresAt < System.currentTimeMillis()) { tickets.remove(ticket); return -1; }
377	    38	            if (t.ip != null && ip != null && !t.ip.equals(ip)) return -1;
378	    39	            if (t.uses[0] >= 3) { tickets.remove(ticket); return -1; }
379	    40	            t.uses[0]++;
