    71	    private record Candidate(long dishId, String name, String category, String spice, long price, int available,
    72	                             String protein, double score) {}
    73	
    74	    private void run(SseEmitter emitter, UserPrincipal user, String prompt, String sessionId) {
    75	        long start = System.currentTimeMillis();
    76	        try {
    77	            List<Candidate> candidates = candidates(user.id());
    78	            List<String> reasons = new ArrayList<>();
    79	            List<Candidate> chosen;
    80	            boolean fallback = llmKey == null || llmKey.isBlank();
    81	            String model = fallback ? "rule-based" : llmModel;
    82	            List<Candidate> llmChosen = fallback ? null : tryLlm(prompt, candidates, reasons);
    83	            if (llmChosen != null) {
    84	                chosen = llmChosen;
    85	            } else {
    86	                fallback = true;
    87	                model = "rule-based";
    88	                chosen = candidates.stream().limit(5).toList();
    89	                reasons.clear();
    90	                for (Candidate c : chosen) reasons.add(reasonFor(c));
    91	            }
    92	            Map<String, Object> meta = new LinkedHashMap<>();
    93	            meta.put("fallback", fallback);
    94	            meta.put("model", model);
    95	            meta.put("sessionId", sessionId);
    96	            emitter.send(SseEmitter.event().reconnectTime(3000L).name("meta").data(Util.json(meta)));
    97	            List<Long> ids = new ArrayList<>();
    98	            for (int i = 0; i < chosen.size(); i++) {
    99	                Candidate c = chosen.get(i);
   100	                ids.add(c.dishId());
   101	                Map<String, Object> dish = new LinkedHashMap<>();
   102	                dish.put("dishId", c.dishId());
   103	                dish.put("name", c.name());
   104	                dish.put("priceCents", c.price());
   105	                dish.put("priceDisplay", Util.money(c.price()));
   106	                dish.put("category", c.category());
   107	                dish.put("available", c.available());
   108	                emitter.send(SseEmitter.event().name("dish").data(Util.json(dish)));
   109	                Map<String, Object> reason = new LinkedHashMap<>();
   110	                reason.put("dishId", c.dishId());
   111	                reason.put("text", i < reasons.size() ? reasons.get(i) : reasonFor(c));
   112	                emitter.send(SseEmitter.event().name("reason").data(Util.json(reason)));
   113	            }
   114	            emitter.send(SseEmitter.event().name("done").data(Util.json(Map.of("dishIds", ids))));
   115	            persist(user.id(), sessionId, prompt, ids, model, fallback, System.currentTimeMillis() - start);
   116	            emitter.complete();
   117	        } catch (Exception e) {
   118	            log.warn("AI recommend failed: {}", e.getMessage());
   119	            try { emitter.completeWithError(e); } catch (Exception ignored) {}
   120	        }
   121	    }
