    18	@Component
    19	public class SseHub {
    20	    private static final Logger log = LoggerFactory.getLogger(SseHub.class);
    21	    private final List<Entry> emitters = new CopyOnWriteArrayList<>();
    22	    private final JdbcTemplate jdbc;
    23	
    24	    public SseHub(JdbcTemplate jdbc) {
    25	        this.jdbc = jdbc;
    26	    }
    27	
    28	    private record Entry(SseEmitter emitter, LocalDate date) {}
    29	
    30	    public SseEmitter subscribe(LocalDate date) {
    31	        SseEmitter emitter = new SseEmitter(0L);
    32	        Entry entry = new Entry(emitter, date);
    33	        emitter.onCompletion(() -> emitters.remove(entry));
    34	        emitter.onTimeout(() -> { emitters.remove(entry); emitter.complete(); });
    35	        emitter.onError(e -> emitters.remove(entry));
    36	        emitters.add(entry);
    37	        try {
    38	            emitter.send(SseEmitter.event().reconnectTime(3000L).name("snapshot").data(Util.json(snapshot(date))));
    39	        } catch (Exception e) {
    40	            emitters.remove(entry);
    41	            emitter.completeWithError(e);
    42	        }
    43	        log.info("SSE subscriber added, active={}", emitters.size());
    44	        return emitter;
    45	    }
    46	
    47	    public List<Map<String, Object>> snapshot(LocalDate date) {
    48	        List<Map<String, Object>> rows = jdbc.queryForList(
    49	                "SELECT s.dish_id, s.total_qty-s.reserved_qty-s.sold_qty AS available FROM dish_daily_stock s "
    50	                        + "JOIN daily_menu m ON m.dish_id=s.dish_id AND m.serve_date=s.serve_date "
    51	                        + "JOIN dishes d ON d.id=s.dish_id AND d.status='ON_SHELF' "
    52	                        + "WHERE s.serve_date=? AND m.publish_status='PUBLISHED' ORDER BY s.dish_id", date);
    53	        List<Map<String, Object>> out = new ArrayList<>();
    54	        for (Map<String, Object> r : rows) {
    55	            Map<String, Object> m = new LinkedHashMap<>();
    56	            m.put("dishId", r.get("dish_id"));
    57	            m.put("available", Math.max(0, Util.intVal(r.get("available"))));
    58	            out.add(m);
    59	        }
    60	        return out;
    61	    }
    62	
    63	    public void publishStock(long dishId, int available) {
    64	        Map<String, Object> data = new LinkedHashMap<>();
    65	        data.put("dishId", dishId);
    66	        data.put("available", Math.max(0, available));
    67	        for (Entry e : emitters) {
    68	            try {
    69	                e.emitter().send(SseEmitter.event().reconnectTime(3000L).name("stock").data(Util.json(data)));
    70	            } catch (Exception ex) {
    71	                emitters.remove(e);
    72	                try { e.emitter().complete(); } catch (Exception ignored) {}
    73	            }
    74	        }
    75	    }
    76	
    77	    @Scheduled(fixedDelay = 15000)
    78	    public void heartbeat() {
    79	        for (Entry e : emitters) {
    80	            try {
    81	                e.emitter().send(SseEmitter.event().comment("ping"));
    82	            } catch (Exception ex) {
    83	                emitters.remove(e);
    84	            }
    85	        }
    86	    }
    87	
    88	    public int activeConnections() { return emitters.size(); }
