200	    @Test
201	    void concurrentSameKeyCreatesExactlyOneOrder() throws Exception {
202	        String token = registerAndLogin("race");
203	        String key = "it-race-" + System.nanoTime();
204	        int n = 5;
205	        ExecutorService pool = Executors.newFixedThreadPool(n);
206	        CountDownLatch start = new CountDownLatch(1);
207	        List<Future<JsonNode>> futures = new ArrayList<>();
208	        for (int i = 0; i < n; i++) {
209	            futures.add(pool.submit(() -> {
210	                start.await();
211	                return submit(token, key, 16L, 1);
212	            }));
213	        }
214	        start.countDown();
215	        List<Long> ids = new ArrayList<>();
216	        for (Future<JsonNode> f : futures) ids.add(f.get(15, TimeUnit.SECONDS).path("data").path("orderId").asLong());
217	        pool.shutdown();
218	        assertEquals(1, ids.stream().distinct().count(), "concurrent same-key submissions must map to one order");
219	        Integer count = jdbc.queryForObject("SELECT COUNT(*) FROM idempotency_records WHERE idem_key=?", Integer.class, key);
220	        assertEquals(1, count);
221	    }
