 33	    /** AC-024/025: six cutoff boundaries + cross-day. */
 34	    @Test
 35	    void cutoffSixBoundariesAndCrossDay() {
 36	        String d = "2026-11-14";
 37	        // 09:59:59 -> today Lunch, no switch
 38	        var r1 = Util.resolveMeal(LocalDate.parse(d), "Lunch", at(d, 9, 59, 59));
 39	        assertEquals(LocalDate.parse(d), r1.date());
 40	        assertEquals("Lunch", r1.meal());
 41	        assertFalse(r1.autoSwitched());
 42	
 43	        // 10:00:00 == cutoff -> closed, auto switch to today Dinner
 44	        var r2 = Util.resolveMeal(LocalDate.parse(d), "Lunch", at(d, 10, 0, 0));
 45	        assertEquals("Dinner", r2.meal());
 46	        assertEquals(LocalDate.parse(d), r2.date());
 47	        assertTrue(r2.autoSwitched());
 48	
 49	        // 10:00:01 -> today Dinner
 50	        var r3 = Util.resolveMeal(LocalDate.parse(d), "Lunch", at(d, 10, 0, 1));
 51	        assertEquals("Dinner", r3.meal());
 52	        assertTrue(r3.autoSwitched());
 53	
 54	        // 14:59:59 -> today Dinner allowed
 55	        var r4 = Util.resolveMeal(LocalDate.parse(d), "Dinner", at(d, 14, 59, 59));
 56	        assertEquals("Dinner", r4.meal());
 57	        assertFalse(r4.autoSwitched());
 58	
 59	        // 15:00:00 == cutoff -> tomorrow Lunch
 60	        var r5 = Util.resolveMeal(LocalDate.parse(d), "Dinner", at(d, 15, 0, 0));
 61	        assertEquals(LocalDate.parse(d).plusDays(1), r5.date());
 62	        assertEquals("Lunch", r5.meal());
 63	        assertTrue(r5.autoSwitched());
 64	
 65	        // 15:00:01 -> tomorrow Lunch
 66	        var r6 = Util.resolveMeal(LocalDate.parse(d), "Dinner", at(d, 15, 0, 1));
 67	        assertEquals(LocalDate.parse(d).plusDays(1), r6.date());
 68	        assertTrue(r6.autoSwitched());
 69	
 70	        // cross-day: tomorrow Lunch requested today 16:00 -> allowed
 71	        var r7 = Util.resolveMeal(LocalDate.parse(d).plusDays(1), "Lunch", at(d, 16, 0, 0));
 72	        assertEquals(LocalDate.parse(d).plusDays(1), r7.date());
 73	        assertEquals("Lunch", r7.meal());
 74	        assertFalse(r7.autoSwitched());
 75	
 76	        // past date rejected
 77	        var ex = assertThrows(com.webox.common.ApiException.class,
 78	                () -> Util.resolveMeal(LocalDate.parse(d).minusDays(1), "Lunch", at(d, 9, 0, 0)));
 79	        assertEquals("VALIDATION_DATE_PAST", ex.getCode());
 80	    }
